CustomField.formula:
IF(
/*If Account is IMGA, stores Reciprocal Spend (IMGA) value */
ISPICKVAL(IM_Hierarchy_Level__c, 'IM Group (IMGA)'), Reciprocal_Spend_IMGA__c ,
IF(
/*If Account is Country Parent, stores Reciprocal Spend (IMGA) value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Parent.Reciprocal_Spend_IMGA__c,
IF(
/*If Account is Sales site, stores Country Parent Account's Reciprocal Spend (IMGA) by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'), Parent.Parent.Reciprocal_Spend_IMGA__c,False)))
